class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        count = {}
        left = max_f = 0
        for right, ch in enumerate(s):
            count[ch] = count.get(ch, 0) + 1
            max_f = max(max_f, count[ch])
            if (right - left + 1) - max_f > k:
                count[s[left]] -= 1
                left += 1
        return len(s) - left
